        [S('🚆 Last train', 'The back of a taxi, 11 pm', 'The last train leaves in 25 minutes. The driver takes an unexpected turn.', 'A heavy bag and a card.', 'To reach the station in time without a row.', 'Sid, taxi driver', 'On the road since dawn, unflappable, loves a shortcut.'),
         S('🛬 From the airport', 'A taxi rank, arrivals', 'You do not know the city. The driver suggests a fixed price.', 'An address on your phone.', 'A fair fare and a quick ride.', 'Paula, driver', 'Chatty, proud of her city, a little pushy on price.'),
         S('🌧 Rainy night', 'A taxi in heavy rain', 'You are late and the driver has a different idea of the route.', 'An umbrella and a hurry.', 'A calm ride and a fair fare.', 'Ben, driver', 'Laid-back, philosophical, hates traffic.')],
